import React, { useState } from 'react';
import { ArrowRight, CheckCircle2, AlertTriangle, Layers, Scissors, ClipboardList } from 'lucide-react';
import { fourPointScore } from './cutting-order-data';
const tone = status => ['COMPLETE','RELEASED'].includes(status)?'bg-emerald-50 text-emerald-800 border-emerald-200':['HOLD','BLOCKED','RECHECK'].includes(status)?'bg-red-50 text-red-800 border-red-200':'bg-amber-50 text-amber-900 border-amber-200';
const Badge=({value})=><span className={`inline-flex border rounded-full px-3 py-1 text-xs font-bold whitespace-nowrap ${tone(value)}`}>{value}</span>;
const Card=({title,children})=><section className="bg-white rounded-2xl border border-slate-200 p-5 md:p-6 space-y-4"><h3 className="text-xl font-bold text-slate-900">{title}</h3>{children}</section>;
export default function CuttingOrderDashboard({orders,order,onSelectOrder,onViewForm}) {
  const [stageKey,setStageKey]=useState('fabric'),[rollId,setRollId]=useState(null);
  const stage=order.stages.find(s=>s.key===stageKey),roll=order.rolls.find(r=>r.id===rollId);
  const points=order.rolls.reduce((n,r)=>n+r.points,0),area=order.rolls.reduce((n,r)=>n+r.yards*r.width/36,0),score=points*100/area;
  const holds=order.rolls.filter(r=>r.disposition==='HOLD').length;
  const metrics=[['Fabric score',score.toFixed(1),'points / 100 yd²',ClipboardList],['Spreading',`${order.actualLayers}/${order.planLayers}`,'actual / planned plies',Layers],['Cut output',order.cutQty,order.cutQty>order.allocation?`${order.cutQty-order.allocation} above table allocation`:'pieces cut',Scissors],['Numbered',`${order.numbered}/${order.cutQty}`,'pieces identified',CheckCircle2],['Panel QC',order.inspected?`${(order.pass/order.inspected*100).toFixed(1)}%`:'Not started',`${order.pass} pass / ${order.inspected} inspected`,AlertTriangle]];
  return <div className="space-y-6 text-base text-slate-700">
    <div className="flex flex-wrap justify-between gap-4 items-end"><div><p className="text-sm font-semibold text-purple-700">Cutting quality / order overview</p><h2 className="text-3xl font-bold text-slate-900 mt-1">{order.mo} · {order.style}</h2><p className="mt-2">{order.buyer} · {order.colour} · PO {order.po} · {order.date}</p></div><div className="flex flex-wrap gap-3"><label className="text-sm font-bold">MO / order<select aria-label="Dashboard order" value={order.mo} onChange={e=>{onSelectOrder(e.target.value);setRollId(null);setStageKey('fabric');}} className="block rounded-lg border border-slate-300 bg-white text-lg p-2 mt-1">{orders.map(o=><option key={o.mo} value={o.mo}>{o.mo} · {o.style}</option>)}</select></label><button onClick={onViewForm} className="self-end inline-flex gap-2 items-center px-4 py-3 rounded-xl bg-purple-700 text-white font-bold">View cutting form<ArrowRight size={18}/></button></div></div>
    <p className="bg-purple-50 border border-purple-100 p-3 rounded-xl text-sm">Demo records · Form and dashboard use the same selected MO and cutting table. Results are simulated. Table {order.table}: {order.allocation} allocated pieces / {order.orderQty} order pieces. QC totals refer to checked pieces, not the whole order.</p>
    <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-5 gap-4">{metrics.map(([label,value,detail,Icon])=><div key={label} className="bg-slate-50 border border-slate-200 p-5 rounded-2xl"><div className="flex justify-between gap-2 text-slate-600"><p className="text-sm font-bold">{label}</p><Icon size={20}/></div><p className="text-3xl font-bold text-slate-900 mt-3">{value}</p><p className="text-sm mt-2">{detail}</p></div>)}</div>
    <Card title="Order process status"><div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-5 gap-3">{order.stages.map((s,i)=><button key={s.key} onClick={()=>setStageKey(s.key)} aria-pressed={stageKey===s.key} className={`text-left p-4 border-2 rounded-xl space-y-3 ${stageKey===s.key?'border-purple-600 bg-purple-50':'border-slate-200 bg-white hover:border-purple-300'}`}><p className="font-bold text-slate-900">{i+1}. {s.name}</p><Badge value={s.status}/><p className="text-sm">{s.time}</p></button>)}</div><div className="bg-slate-50 rounded-xl p-4 space-y-2"><h4 className="text-lg font-bold">{stage.name} · {stage.record}</h4><p>{stage.summary}</p><p className="text-sm"><strong>Owner:</strong> {stage.owner}</p><ul className="list-disc pl-5 text-sm space-y-1">{stage.checks.map(c=><li key={c}>{c}</li>)}</ul></div></Card>
    <Card title="Fabric inspection · 4-point results"><div className="flex flex-wrap gap-4 justify-between"><p>{order.rolls.length} rolls / {order.rolls.reduce((n,r)=>n+r.yards,0)} inspected yd · <strong>{holds} on hold</strong></p><p className="text-sm">Demo roll limit: ≤ {order.limit} points / 100 yd²</p></div><div className="overflow-x-auto"><table className="w-full text-left text-base whitespace-nowrap"><thead className="bg-slate-50 text-sm"><tr>{['Roll / shade','Inspected yd','Width (in)','Points','Pts / 100 yd²','QA disposition','Record'].map(x=><th key={x} className="p-3 border-b">{x}</th>)}</tr></thead><tbody>{order.rolls.map(r=><tr key={r.id} className="border-b border-slate-100"><td className="p-3"><strong>{r.id}</strong><p className="text-sm text-slate-500">Shade {r.shade}</p></td><td className="p-3">{r.yards}</td><td className="p-3">{r.width}</td><td className="p-3">{r.points}</td><td className="p-3 font-bold">{fourPointScore(r).toFixed(1)}</td><td className="p-3"><Badge value={r.disposition}/></td><td className="p-3"><button aria-label={`View fabric inspection ${r.id}`} onClick={()=>setRollId(rollId===r.id?null:r.id)} className="text-purple-700 font-bold underline">{rollId===r.id?'Close':'View'}</button></td></tr>)}</tbody></table></div>{roll&&<div className="rounded-xl bg-slate-50 border border-slate-200 p-4 space-y-2" role="region" aria-label="Fabric roll inspection detail"><h4 className="font-bold text-lg">{roll.id} · inspection record</h4><p>Lot {roll.lot}; shade group {roll.shade}. Defects recorded: {roll.defects}.</p><p>{roll.points} × 3600 ÷ ({roll.yards} × {roll.width}) = <strong>{fourPointScore(roll).toFixed(1)} points / 100 yd²</strong>.</p><p>Inspector: Fabric QA · Disposition: {roll.disposition}. {roll.disposition==='HOLD'?'Roll segregated; entire job blocked until QA resolves the lot.':'Released for the identified lot; do not mix shade groups.'}</p></div>}<p className="text-sm text-slate-500">Score = defect points × 3600 ÷ (inspected yards × usable width in inches). Lot score uses total inspected area, not an unweighted roll average. The displayed 40-point limit is a demo buyer rule; other tests, shade and QA disposition can still block a lot. <a href="https://www.psscive.ac.in/storage/uploads/textbooks/pdf/english/fabric-checker-english-class-12.pdf" target="_blank" rel="noreferrer" className="underline text-purple-700">Fabric inspection reference</a></p></Card>
    <div className="grid xl:grid-cols-2 gap-6"><Card title="Spreading and cutting reconciliation"><dl className="grid grid-cols-2 gap-4">{[['Table',order.table],['Marker',order.marker],['Marker length',`${order.markerLength} yd`],['Spread yards',`${order.spreadYards} yd`],['Planned / actual plies',`${order.planLayers} / ${order.actualLayers}`],['Size ratio S / M / L / XL',order.ratio.join(' / ')],['Pieces per ply',order.ratio.reduce((a,b)=>a+b,0)],['Cut pieces',order.cutQty]].map(([k,v])=><div key={k}><dt className="text-sm text-slate-500">{k}</dt><dd className="font-bold text-lg text-slate-900">{v}</dd></div>)}</dl><p className="text-sm">Expected pieces = actual plies × size-ratio total = {order.actualLayers} × {order.ratio.reduce((a,b)=>a+b,0)} = {order.cutQty}. Spreading uses released rolls only.</p></Card><Card title="Numbering, bundles and panel QC"><dl className="grid grid-cols-2 gap-4">{[['Number range',order.numberRange],['Bundles / max 10 pcs',order.bundles],['Awaiting numbering',Math.max(0,order.cutQty-order.numbered)],['Numbered, not yet QC checked',order.numbered-order.inspected],['Inspected / passed',`${order.inspected} / ${order.pass}`],['Rejected / pending reinspection',order.rejected]].map(([k,v])=><div key={k}><dt className="text-sm text-slate-500">{k}</dt><dd className="font-bold text-lg text-slate-900">{v}</dd></div>)}</dl><p className="text-sm">Bundle IDs {order.numbered?`${order.mo}-B01 to B${String(order.bundles).padStart(2,'0')}`:'not issued'}. Each number links matching panels to size, shade, roll, lay and marker. Numbering progress is not QA approval to sew.</p></Card></div>
    <Card title="Exceptions and next action"><div className="overflow-x-auto"><table className="w-full text-left"><thead className="bg-slate-50 text-sm"><tr>{['Issue','Owner / due','Required action','Status'].map(x=><th key={x} className="p-3">{x}</th>)}</tr></thead><tbody>{order.actions.map(a=><tr key={a.issue} className="border-b"><td className="p-3 font-bold">{a.issue}</td><td className="p-3">{a.owner}<p className="text-sm">Due {a.due}</p></td><td className="p-3">{a.next}</td><td className="p-3"><Badge value={a.state}/></td></tr>)}</tbody></table></div><p className="text-sm font-semibold">{!order.actions.length?'No open panel-QC action; QA release and downstream controls still apply.':holds?'Material HOLD blocks spreading, cutting and numbering.':order.rejected?'Affected panels remain held until correction and QA reinspection.':'Only QC-accepted output can move forward; complete the remaining checks.'}</p></Card>
    <Card title="Other orders"><div className="overflow-x-auto"><table className="w-full text-left whitespace-nowrap"><thead className="text-sm bg-slate-50"><tr>{['MO / buyer','Style / colour','Cut / numbered','QC pass / checked','Material status',''].map((h,i)=><th key={i} className="p-3">{h}</th>)}</tr></thead><tbody>{orders.map(o=><tr key={o.mo} className={`border-b ${o.mo===order.mo?'bg-purple-50':''}`}><td className="p-3 font-bold">{o.mo}<p className="font-normal text-sm">{o.buyer}</p></td><td className="p-3">{o.style}<p className="text-sm">{o.colour}</p></td><td className="p-3">{o.cutQty} / {o.numbered}</td><td className="p-3">{o.pass} / {o.inspected}</td><td className="p-3"><Badge value={o.rolls.some(r=>r.disposition==='HOLD')?'HOLD':'RELEASED'}/></td><td className="p-3"><button aria-label={`View cutting dashboard ${o.mo}`} onClick={()=>{onSelectOrder(o.mo);setRollId(null);setStageKey('fabric');}} className="text-purple-700 font-bold underline">View order</button></td></tr>)}</tbody></table></div></Card>
  </div>;
}
